// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract Crowdfunding {
    uint256 private nextCampaignId;

    error InvalidGoal();
    error InvalidDuration();
    error CampaignNotFound();
    error CampaignEnded();
    error CampaignStillRunning();
    error GoalReached();
    error GoalNotReached();
    error ZeroDonation();
    error NotCampaignOwner();
    error AlreadyWithdrawn();
    error NoDonationFound();

    struct Campaign {
        uint256 id;
        address payable owner;
        string title;
        string description;
        uint256 goal;
        uint256 deadline;
        uint256 amountCollected;
        bool withdrawn;
    }

    mapping(uint256 => Campaign) private campaigns;

    mapping(uint256 => mapping(address => uint256)) public donations;

    mapping(uint256 => address[]) private donors;

    event CampaignCreated(uint256 indexed campaignId,address indexed owner,string title,uint256 goal,uint256 deadline);

    event DonationReceived(uint256 indexed campaignId,address indexed donor,uint256 amount);

    event FundsWithdrawn(uint256 indexed campaignId, uint256 amount);

    event Refunded( uint256 indexed campaignId,address indexed donor,uint256 amount);

    modifier campaignExists(uint256 id) {
        if (id >= nextCampaignId) revert CampaignNotFound();
        _;
    }

    constructor() {
        nextCampaignId = 0;
    }

    function createCampaign(string calldata title,string calldata description,uint256 goal, uint256 durationInDays)
     external {
        if (goal == 0) revert InvalidGoal();

        if (durationInDays == 0) revert InvalidDuration();

        Campaign storage campaign = campaigns[nextCampaignId];

        campaign.id = nextCampaignId;
        campaign.owner = payable(msg.sender);
        campaign.title = title;
        campaign.description = description;
        campaign.goal = goal;
        campaign.deadline = block.timestamp + (durationInDays * 1 days);

        emit CampaignCreated(nextCampaignId,msg.sender,title,goal,campaign.deadline);

        nextCampaignId++;
    }

    function donate(uint256 id) external payable campaignExists(id) {
        Campaign storage campaign = campaigns[id];

        if (block.timestamp >= campaign.deadline) revert CampaignEnded();

        if (msg.value == 0) revert ZeroDonation();

        if (donations[id][msg.sender] == 0) {
            donors[id].push(msg.sender);
        }

        donations[id][msg.sender] += msg.value;

        campaign.amountCollected += msg.value;

        emit DonationReceived(id, msg.sender, msg.value);
    }

    function withdraw(uint256 id) external campaignExists(id) {
        Campaign storage campaign = campaigns[id];

        if (msg.sender != campaign.owner) revert NotCampaignOwner();

        if (block.timestamp < campaign.deadline) revert CampaignStillRunning();

        if (campaign.amountCollected < campaign.goal) revert GoalNotReached();

        if (campaign.withdrawn) revert AlreadyWithdrawn();

        campaign.withdrawn = true;

        uint256 amount = campaign.amountCollected;

        campaign.owner.transfer(amount);

        emit FundsWithdrawn(id, amount);
    }

    function refund(uint256 id) external campaignExists(id) {
        Campaign storage campaign = campaigns[id];

        if (block.timestamp < campaign.deadline) revert CampaignStillRunning();

        if (campaign.amountCollected >= campaign.goal) revert GoalReached();

        uint256 donated = donations[id][msg.sender];

        if (donated == 0) revert NoDonationFound();

        donations[id][msg.sender] = 0;

        payable(msg.sender).transfer(donated);

        emit Refunded(id, msg.sender, donated);
    }

    function getCampaign(uint256 id )
         external view campaignExists(id) returns (Campaign memory) {
        return campaigns[id];
    }

    function getCampaignCount() external view returns (uint256) {
        return nextCampaignId;
    }

    function getDonors(uint256 id)
    external view campaignExists(id) returns (address[] memory) {
        return donors[id];
    }

    function getDonation(uint256 id,address donor) 
    external view returns (uint256) {
        return donations[id][donor];
    }

    function contractBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

